async function(variables) {
  var g = new GridWidget(variables.element, variables.dataSource);
  g.editable = false;
	g.sortable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = false;
	g.groupable = false;
  g.commands.push({ name: "view", icon: "k-i-share", text: "[resource_shortdisplayname[View]]", href: "/Company/Details?Id=#:Id#" });
  g.columns = [
    {field: "Perspective", title: "[resource_displayname[perspective]]", template: "#=window.B2B.perspectives[Perspective]#", width: 120},
    {field: "Name", title: "[resource_displayname[name]]"},
    {field: "DebtorReference", title: "[resource_displayname[debtorreference]]"},
    {field: "DebtorVATReference", title: "[resource_displayname[debtorvatreference]]", width: 100}
  ];
  variables.companyGrid = g;
  return g;
}
